#define NOMINMAX
#include "tokenizer_file.hpp"
#include "byte_bpe_incremental.hpp"
#include <chrono>
#include <cstdio>
int main(){try{MEMORYSTATUSEX mem{};mem.dwLength=sizeof(mem);if(!GlobalMemoryStatusEx(&mem))throw std::runtime_error("memory query");printf("available_RAM_MiB=%llu\n",(unsigned long long)(mem.ullAvailPhys/1048576));fflush(stdout);if(mem.ullAvailPhys<10ull*1024*1024*1024)throw std::runtime_error("require 10GiB free RAM for indexed reference fit");std::ifstream in("build/bpe_training_messages.bin",std::ios::binary);std::string raw((std::istreambuf_iterator<char>(in)),{});if(!in||raw.size()<4||raw.substr(0,4)!="BTM1")throw std::runtime_error("input");size_t pos=4;std::vector<std::string>messages;while(pos<raw.size()){if(pos+4>raw.size())throw std::runtime_error("length");uint32_t n=0;for(int j=0;j<4;++j)n|=uint32_t((unsigned char)raw[pos++])<<(8*j);if(n>65536||n>raw.size()-pos)throw std::runtime_error("body");messages.push_back(raw.substr(pos,n));pos+=n;}std::string digest=tao::text::sha256(raw);printf("messages=%zu corpus_SHA256=%s\n",messages.size(),digest.c_str());fflush(stdout);auto start=std::chrono::steady_clock::now();auto b=tao::text::fit_incremental(messages,16123);if(b.merges.size()!=16123)throw std::runtime_error("insufficient merges");auto bytes=tao::text::serialize_tokenizer(b);std::ifstream existing("build/formal_tokenizer.bbp",std::ios::binary);if(existing.good())throw std::runtime_error("refuse overwrite");std::ofstream out("build/formal_tokenizer.bbp",std::ios::binary);out.write(bytes.data(),bytes.size());out.close();if(!out)throw std::runtime_error("write");std::ofstream manifest("build/formal_tokenizer_manifest.txt");manifest<<"corpus_sha256="<<digest<<"\ntokenizer_sha256="<<tao::text::sha256(bytes)<<"\nmerges="<<b.merges.size()<<"\nmessages="<<messages.size()<<"\n";printf("PASS merges=%zu tokenizer_SHA256=%s seconds=%.3f\n",b.merges.size(),tao::text::sha256(bytes).c_str(),std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count());return 0;}catch(const std::exception&e){printf("FAIL %s\n",e.what());return 1;}}
